const fetch = require('node-fetch');
const apiKey = '';  // 在此处输入您的Perplexity API密钥。

const query = $query;

const options = {
	method: 'POST',
	headers: {
		'Content-Type': 'application/json',
		'Authorization': `Bearer ${apiKey}`
	},
	body: JSON.stringify({
		model: 'sonar',  // 模型
		messages: [
			{
				role: 'system',
				content: '您是一名市场研究助手。'
			},
			{
				role: 'user',
				content: query
			}
		]
	})
};

try {
	console.log(`发送请求，查询内容：${query}`);
	const response = await fetch('https://api.perplexity.ai/chat/completions', options);
	const data = await response.json();

	if (!response.ok) {
		throw new Error(`API错误：${response.status} ${response.statusText} - ${JSON.stringify(data)}`);
	}

	console.log('API响应:', data);
	return JSON.stringify(data);
} catch (error) {
	console.error('从Perplexity AI获取数据时发生错误:', error);
	return `从Perplexity AI获取数据时发生错误：${error.message}`;
}
